54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    private final OwnerAuditor ownerAuditor;
70	
71	    private final WelcomeNotifier welcomeNotifier;
72	
73	    private final IdempotencyStore idempotencyStore;
74	
75	    private final HttpServletRequest request;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 OwnerAuditor ownerAuditor,
82	                                 WelcomeNotifier welcomeNotifier,
83	                                 IdempotencyStore idempotencyStore,
84	                                 HttpServletRequest request) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	        this.ownerAuditor = ownerAuditor;
90	        this.welcomeNotifier = welcomeNotifier;
91	        this.idempotencyStore = idempotencyStore;
92	        this.request = request;
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
98	        Collection<Owner> owners;
99	        if (lastName != null) {
100	            owners = this.clinicService.findOwnerByLastName(lastName);
101	        } else {
102	            owners = this.clinicService.findAllOwners();
103	        }
104	        if (owners.isEmpty()) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
113	        Owner owner = this.clinicService.findOwnerById(ownerId);
114	        if (owner == null) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
123	        String idempotencyKey = this.request.getHeader("Idempotency-Key");
124	        ResponseEntity<OwnerDto> replay = replayCreatedOwner(idempotencyKey);
125	        if (replay != null) {
126	            return replay;
127	        }
128	        HttpHeaders headers = new HttpHeaders();
129	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
130	        if (this.clinicService.isRegistrationDateInFuture(owner.getRegistrationDate())) {
131	            throw new BusinessRuleViolationException(HttpStatus.BAD_REQUEST,
132	                "Invalid registration date", "The registration date must not be in the future");
133	        }
134	        owner.setRegistrationDate(this.clinicService.resolveRegistrationDate(owner.getRegistrationDate()));
135	        if (this.clinicService.isDailyOwnerLimitReached(owner.getRegistrationDate())) {
136	            throw new BusinessRuleViolationException(HttpStatus.TOO_MANY_REQUESTS,
137	                "Daily owner limit reached", "The daily limit for new owner registrations has been reached");
138	        }
139	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
140	            throw new BusinessRuleViolationException(HttpStatus.CONFLICT,
141	                "City at capacity", "The city has reached its maximum number of registered owners");
142	        }
143	        // Assign the deterministic householdId (derived from last name and postcode) so owners in
144	        // the same household share it automatically.
145	        this.clinicService.assignHousehold(owner);
146	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
147	        // Reject an exact duplicate: an owner whose whole identity key (normalized telephone,
148	        // email and the Soundex of the last name) already exists.
149	        if (this.clinicService.existsOwnerWithIdentityKey(owner)) {
150	            throw new BusinessRuleViolationException(HttpStatus.CONFLICT,
151	                "Duplicate owner", "An owner with the same identity already exists");
152	        }
153	        owner.setNamesakeCount((int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
154	        owner.setHouseholdSize((int) this.clinicService.countHouseholdMembers(owner));
155	        // Cap the membership level so a new household member never outranks its household by more
156	        // than one level above its current highest-ranked member.
157	        owner.setMembershipLevel(this.clinicService.resolveCappedMembershipLevel(owner));
158	        owner.setBulkSignupWarning(this.clinicService.isBulkSignupWarranted(owner.getRegistrationDate()));
159	        owner.setCapacityWarning(this.clinicService.isCityApproachingCapacity(owner.getCity()));
160	        // Flag a soft match unless this is a declared household member (a declared member is not a
161	        // suspected duplicate): an existing owner sharing this owner's postcode and last-name Soundex
162	        // with a different identity key.
163	        if (!declaredHouseholdMember) {
164	            Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
165	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
166	            owner.setPossibleDuplicateOf(possibleDuplicateOf);
167	        }
168	        this.clinicService.saveOwner(owner);
169	        this.ownerAuditor.auditCreated(owner);
170	        this.welcomeNotifier.enqueueWelcome(owner);
171	        this.idempotencyStore.record(idempotencyKey, owner.getId());
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    /**
179	     * If {@code idempotencyKey} was already used to create an owner, return that original owner
180	     * with {@code 200 OK} so a repeated create replays the first result instead of creating a
181	     * duplicate. Returns {@code null} when there is nothing to replay (no key, or key unseen).
182	     */
183	    private ResponseEntity<OwnerDto> replayCreatedOwner(String idempotencyKey) {
184	        return this.idempotencyStore.find(idempotencyKey)
185	            .map(this.clinicService::findOwnerById)
186	            .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
187	            .orElse(null);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
193	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
194	        if (currentOwner == null) {
195	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	        }
197	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
198	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
199	        currentOwner.setAddress(ownerMapper.composeAddress(ownerFieldsDto));
200	        currentOwner.setCity(ownerFieldsDto.getCity());
201	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
202	        currentOwner.setLastName(ownerFieldsDto.getLastName());
203	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
204	        this.clinicService.saveOwner(currentOwner);
205	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Transactional
210	    @Override
211	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        this.clinicService.deleteOwner(owner);
217	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner == null) {
225	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	        }
227	        HttpHeaders headers = new HttpHeaders();
228	        Pet pet = petMapper.toPet(petFieldsDto);
229	        owner.setId(ownerId);
230	        pet.setOwner(owner);
231	        pet.getType().setName(null);
232	        this.clinicService.savePet(pet);
233	        PetDto petDto = petMapper.toPetDto(pet);
234	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
235	            .buildAndExpand(pet.getId()).toUri());
236	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
237	    }
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
242	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
243	        if (currentOwner != null) {
244	            Pet currentPet = this.clinicService.findPetById(petId);
245	            if (currentPet != null) {
246	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
247	                currentPet.setName(petFieldsDto.getName());
248	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
249	                this.clinicService.savePet(currentPet);
250	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
251	            }
252	        }
253	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	    }
255	
256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Override
258	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
259	        HttpHeaders headers = new HttpHeaders();
260	        Visit visit = visitMapper.toVisit(visitFieldsDto);
261	        Pet pet = new Pet();
262	        pet.setId(petId);
263	        visit.setPet(pet);
264	        this.clinicService.saveVisit(visit);
265	        VisitDto visitDto = visitMapper.toVisitDto(visit);
266	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
267	            .buildAndExpand(visit.getId()).toUri());
268	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
269	    }
270	
271	
272	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
273	    @Override
274	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
275	        Owner owner = this.clinicService.findOwnerById(ownerId);
276	        if (owner != null) {
277	            Pet pet = owner.getPet(petId);
278	            if (pet != null) {
279	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
280	            }
281	        }
282	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	    }
284	}
