32	/**
33	 * Simple JavaBean domain object representing an owner.
34	 *
35	 * @author Ken Krebs
36	 * @author Juergen Hoeller
37	 * @author Sam Brannen
38	 * @author Michael Isvy
39	 */
40	@Entity
41	@Table(name = "owners")
42	public class Owner extends Person {
43	    @Column(name = "title")
44	    private String title;
45	
46	    @Column(name = "address")
47	    @NotEmpty
48	    private String address;
49	
50	    @Column(name = "address_line1")
51	    private String addressLine1;
52	
53	    @Column(name = "address_line2")
54	    private String addressLine2;
55	
56	    @Column(name = "city")
57	    @NotEmpty
58	    private String city;
59	
60	    @Column(name = "telephone")
61	    @NotEmpty
62	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ and 8 to 15 digits)")
63	    private String telephone;
64	
65	    @Column(name = "email")
66	    private String email;
67	
68	    @Column(name = "postcode")
69	    private String postcode;
70	
71	    @Column(name = "registration_date", columnDefinition = "DATE")
72	    private LocalDate registrationDate;
73	
74	    @Column(name = "birth_date", columnDefinition = "DATE")
75	    private LocalDate birthDate;
76	
77	    @Column(name = "member_id")
78	    private String memberId;
79	
80	    @Column(name = "household_id")
81	    private String householdId;
82	
83	    @Column(name = "namesake_count")
84	    private Integer namesakeCount;
85	
86	    @Column(name = "household_size")
87	    private Integer householdSize;
88	
89	    @Column(name = "membership_level")
90	    private Integer membershipLevel;
91	
92	    @Column(name = "bulk_signup_warning")
93	    private boolean bulkSignupWarning;
94	
95	    @Column(name = "capacity_warning")
96	    private boolean capacityWarning;
97	
98	    @Column(name = "possible_duplicate")
99	    private boolean possibleDuplicate;
100	
101	    @Column(name = "possible_duplicate_of")
102	    private Integer possibleDuplicateOf;
103	
104	    @Column(name = "deleted")
105	    private boolean deleted;
106	
107	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
108	    private Set<Pet> pets;
109	
110	    public String getTitle() {
111	        return this.title;
112	    }
113	
114	    public void setTitle(String title) {
115	        this.title = title;
116	    }
117	
118	    /**
119	     * The owner's salutation: the {@link #title} followed by a space and the last name when a title
120	     * is supplied, otherwise just the last name.
121	     */
122	    @Transient
123	    public String getSalutation() {
124	        return (this.title == null || this.title.isBlank())
125	            ? this.lastName
126	            : this.title + " " + this.lastName;
127	    }
128	
129	    public String getAddress() {
130	        return this.address;
131	    }
132	
133	    public void setAddress(String address) {
134	        this.address = address;
135	    }
136	
137	    public String getAddressLine1() {
138	        return this.addressLine1;
139	    }
140	
141	    public void setAddressLine1(String addressLine1) {
142	        this.addressLine1 = addressLine1;
143	    }
144	
145	    public String getAddressLine2() {
146	        return this.addressLine2;
147	    }
148	
149	    public void setAddressLine2(String addressLine2) {
150	        this.addressLine2 = addressLine2;
151	    }
152	
153	    public String getCity() {
154	        return this.city;
155	    }
156	
157	    public void setCity(String city) {
158	        this.city = city;
159	    }
160	
161	    public String getTelephone() {
162	        return this.telephone;
163	    }
164	
165	    public void setTelephone(String telephone) {
166	        this.telephone = telephone;
167	    }
168	
169	    public String getEmail() {
170	        return this.email;
171	    }
172	
173	    /**
174	     * Stores the email in its canonical lower-cased form so it is always persisted and
175	     * returned lower-cased, regardless of the casing supplied by the client.
176	     */
177	    public void setEmail(String email) {
178	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
179	    }
180	
181	    public String getPostcode() {
182	        return this.postcode;
183	    }
184	
185	    public void setPostcode(String postcode) {
186	        this.postcode = postcode;
187	    }
188	
189	    public LocalDate getRegistrationDate() {
190	        return this.registrationDate;
191	    }
192	
193	    public void setRegistrationDate(LocalDate registrationDate) {
194	        this.registrationDate = registrationDate;
195	    }
196	
197	    public LocalDate getBirthDate() {
198	        return this.birthDate;
199	    }
200	
201	    public void setBirthDate(LocalDate birthDate) {
202	        this.birthDate = birthDate;
203	    }
204	
205	    /**
206	     * The fiscal year of the owner's {@link #registrationDate}, as the {@code "FY<YY>"} label of the
207	     * fiscal year (starting 1 July) that contains the business-day-adjusted registration date.
208	     */
209	    @Transient
210	    public String getFiscalYear() {
211	        return FiscalYear.label(this.registrationDate);
212	    }
213	
214	    /**
215	     * The owner's tenure in fiscal years: the number of fiscal years elapsed from its
216	     * {@link #registrationDate} to the current date. An owner registered in the current fiscal year
217	     * has zero tenure.
218	     */
219	    @Transient
220	    public int getTenureFiscalYears() {
221	        return FiscalYear.yearsBetween(this.registrationDate, LocalDate.now());
222	    }
223	
224	    /**
225	     * The owner's age band derived from {@link #birthDate} against {@link #registrationDate}, or
226	     * {@code null} when no birth date was supplied.
227	     */
228	    @Transient
229	    public AgeBand getAgeBand() {
230	        return this.birthDate == null ? null : AgeBand.of(this.birthDate, this.registrationDate);
231	    }
232	
233	    /**
234	     * The owner's stable member id, formatted {@code <REGION><FY><HASH8><CHK>}. It unifies what were
235	     * previously the separate customer code and membership number into a single identifier, and is
236	     * the owner's primary identifier for audit and downstream consumers.
237	     */
238	    public String getMemberId() {
239	        return this.memberId;
240	    }
241	
242	    public void setMemberId(String memberId) {
243	        this.memberId = memberId;
244	    }
245	
246	    public String getHouseholdId() {
247	        return this.householdId;
248	    }
249	
250	    public void setHouseholdId(String householdId) {
251	        this.householdId = householdId;
252	    }
253	
254	    public Integer getNamesakeCount() {
255	        return this.namesakeCount;
256	    }
257	
258	    public void setNamesakeCount(Integer namesakeCount) {
259	        this.namesakeCount = namesakeCount;
260	    }
261	
262	    public Integer getHouseholdSize() {
263	        return this.householdSize;
264	    }
265	
266	    public void setHouseholdSize(Integer householdSize) {
267	        this.householdSize = householdSize;
268	    }
269	
270	    /**
271	     * The owner's persisted membership level, capped on creation so it never exceeds one above the
272	     * highest level among the owner's household members. {@code null} for owners created before the
273	     * level was resolved, in which case the level is derived on read from the membership points.
274	     */
275	    public Integer getMembershipLevel() {
276	        return this.membershipLevel;
277	    }
278	
279	    public void setMembershipLevel(Integer membershipLevel) {
280	        this.membershipLevel = membershipLevel;
281	    }
