102	     * Groups the owner's version-2 identifiers — {@code memberId}, {@code identityKey} and
103	     * {@code householdId} — under the nested {@code identity} object.
104	     */
105	    default OwnerIdentityDto resolveIdentity(Owner owner) {
106	        OwnerIdentityDto identity = new OwnerIdentityDto();
107	        identity.setMemberId(owner.getMemberId());
108	        identity.setIdentityKey(owner.getIdentityKey());
109	        identity.setHouseholdId(owner.getHouseholdId());
