113	    /**
114	     * Derives the owner's IANA timezone from its {@linkplain #resolveLocality(Owner) locality}
115	     * (canonical region) via the fixed region-to-timezone table, or {@code null} when the locality
116	     * has no known timezone.
117	     */
118	    default String resolveTimezone(Owner owner) {
119	        return TimezoneResolver.resolve(resolveLocality(owner));
120	    }
