122	    /** The minimum tenure, in fiscal years, an owner must exceed to earn the tenure membership points. */
123	    int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
124	
125	    /** The minimum household size that earns the household membership points. */
126	    int HOUSEHOLD_POINTS_THRESHOLD = 3;
127	
128	    /**
129	     * Resolves the owner's membership points: starts at {@code 0}, plus {@code 2} when an email is
130	     * present, plus {@code 1} when the owner has no namesakes (namesakeCount is 0), plus {@code 2}
131	     * when the owner belongs to a household of {@value #HOUSEHOLD_POINTS_THRESHOLD} or more, plus
132	     * {@code 3} when the owner's tenure exceeds {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS} fiscal year.
133	     */
134	    default Integer resolveMembershipPoints(Owner owner) {
135	        int points = 0;
136	        if (hasEmail(owner)) {
137	            points += 2;
138	        }
139	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
140	            points += 1;
141	        }
142	        Integer householdSize = owner.getHouseholdSize();
143	        if (householdSize != null && householdSize >= HOUSEHOLD_POINTS_THRESHOLD) {
144	            points += 2;
145	        }
146	        if (owner.getTenureFiscalYears() > TENURE_POINTS_THRESHOLD_FISCAL_YEARS) {
147	            points += 3;
148	        }
149	        return points;
150	    }
151	
152	    /**
153	     * Resolves the owner's effective membership level: the level persisted (capped) on creation when
154	     * present, otherwise the level {@linkplain #deriveMembershipLevel derived} from its membership
155	     * points.
156	     */
157	    default Integer resolveMembershipLevel(Owner owner) {
158	        Integer stored = owner.getMembershipLevel();
159	        return stored != null ? stored : deriveMembershipLevel(owner);
160	    }
161	
162	    /**
163	     * Derives the owner's numeric membership level from its {@linkplain #resolveMembershipPoints
164	     * membership points}: level {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
165	     * {@code 3} for {@code 4-5} and {@code 4} for {@code 6} or more.
166	     */
167	    default Integer deriveMembershipLevel(Owner owner) {
168	        int points = resolveMembershipPoints(owner);
169	        if (points <= 1) {
170	            return 1;
171	        }
172	        if (points <= 3) {
173	            return 2;
174	        }
175	        if (points <= 5) {
176	            return 3;
177	        }
178	        return 4;
179	    }
180	
181	    /** The minimum membership level that qualifies an owner for the {@code PREMIUM} tier. */
182	    int PREMIUM_TIER_MIN_LEVEL = 3;
183	
184	    /**
185	     * Resolves the owner's segment, formatted {@code "<TIER>_<AREA>"}. TIER is {@code "PREMIUM"} when
186	     * the owner's {@linkplain #resolveMembershipLevel membership level} is at least
187	     * {@value #PREMIUM_TIER_MIN_LEVEL}, otherwise {@code "STANDARD"}. AREA is {@code "METRO"} when the
188	     * owner's {@linkplain #resolveLocality locality} is a known region, otherwise {@code "REGIONAL"}.
189	     */
190	    default String resolveOwnerSegment(Owner owner) {
191	        String tier = resolveMembershipLevel(owner) >= PREMIUM_TIER_MIN_LEVEL ? "PREMIUM" : "STANDARD";
192	        String area = LocalityResolver.isKnownRegion(resolveLocality(owner)) ? "METRO" : "REGIONAL";
193	        return tier + "_" + area;
194	    }
