203	
204	    /**
205	     * Resolves the owner's risk flag: {@code true} when any risk signal holds — the owner is a
206	     * possible duplicate, its email domain is
207	     * {@linkplain DisposableEmailRule#isDisposableAdjacent(String) disposable-adjacent}, or its
208	     * city was over its soft capacity (the capacity warning) when the owner was created — otherwise
209	     * {@code false}.
210	     */
211	    default boolean resolveRiskFlag(Owner owner) {
212	        return owner.isPossibleDuplicate()
213	            || DisposableEmailRule.isDisposableAdjacent(owner.getEmail())
214	            || owner.isCapacityWarning();
215	    }
