239	    /**
240	     * Store the address in its canonical form (trimmed, whitespace-collapsed, upper-cased and with
241	     * common abbreviations expanded), so it is always persisted, returned and compared normalized.
242	     */
243	    @Named("normalizeAddress")
244	    default String normalizeAddress(String address) {
245	        return AddressNormalizer.normalize(address);
246	    }
