248	    /**
249	     * Compose the owner's canonical {@code address} from the supplied fields, preferring the
250	     * structured form: when {@code addressLine1} is present it is the normalized {@code addressLine1}
251	     * with a single space and the normalized {@code addressLine2} appended when that line is present;
252	     * otherwise it falls back to the normalized flat {@code address}. Composing into the single
253	     * {@code address} field keeps everything that reads the address (household hash, postcode
254	     * validation, locality) consistent whichever form was supplied.
255	     */
256	    default String composeAddress(OwnerFieldsDto ownerDto) {
257	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
258	        if (line1 == null || line1.isBlank()) {
259	            return normalizeAddress(ownerDto.getAddress());
260	        }
261	        String line2 = normalizeAddress(ownerDto.getAddressLine2());
262	        return (line2 == null || line2.isBlank()) ? line1 : line1 + " " + line2;
263	    }
