263	    public boolean existsOwnerWithIdentityKey(Owner owner) throws DataAccessException {
264	        String identityKey = owner.getIdentityKey();
265	        // The identity key hashes the (normalized) telephone among its inputs, so owners can only
266	        // share a key when they share a telephone; it is therefore enough to compare against the
267	        // owners already stored with the same telephone. Soft-deleted owners are ignored, so a
268	        // duplicate is allowed once the only match has been deleted.
269	        return ownerRepository.findByTelephone(owner.getTelephone()).stream()
270	            .filter(existing -> !existing.isDeleted())
271	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
