276	     * postcode and the {@linkplain Soundex Soundex} code of its last name but carrying a different
277	     * identity key, so it is not a hard identity-key duplicate. Returns the matching owner's id (the
278	     * lowest when several match), or {@code null} when the owner has no postcode or nothing matches.
279	     */
280	    @Override
281	    @Transactional(readOnly = true)
282	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
283	        if (owner.getPostcode() == null) {
284	            return null;
285	        }
286	        String lastNameSoundex = Soundex.encode(owner.getLastName());
287	        String identityKey = owner.getIdentityKey();
288	        return ownerRepository.findByPostcode(owner.getPostcode()).stream()
289	            .filter(existing -> !existing.isDeleted())
290	            .filter(existing -> lastNameSoundex.equals(Soundex.encode(existing.getLastName())))
291	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
292	            .map(Owner::getId)
293	            .min(Integer::compareTo)
294	            .orElse(null);
295	    }
