328	    static final long DAILY_OWNER_LIMIT = 100;
329	
330	    @Override
331	    public boolean isRegistrationDateInFuture(LocalDate registrationDate) {
332	        return registrationDate != null && registrationDate.isAfter(LocalDate.now());
333	    }
334	
335	    @Override
336	    public LocalDate resolveRegistrationDate(LocalDate registrationDate) {
337	        LocalDate effectiveDate = registrationDate == null ? LocalDate.now() : registrationDate;
338	        return BusinessDay.rollForward(effectiveDate);
339	    }
340	
341	    @Override
342	    @Transactional(readOnly = true)
343	    public boolean isDailyOwnerLimitReached(LocalDate registrationDate) throws DataAccessException {
344	        return ownerRepository.countByRegistrationDate(registrationDate) >= DAILY_OWNER_LIMIT;
345	    }
346	
347	    /**
348	     * The number of owners that may be registered on a given day before further sign-ups for that
349	     * day are flagged with a bulk-signup warning. Once more than this many owners already exist for
350	     * the day, subsequent creates carry the warning.
351	     */
352	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
353	
354	    @Override
355	    @Transactional(readOnly = true)
356	    public boolean isBulkSignupWarranted(LocalDate registrationDate) throws DataAccessException {
357	        return ownerRepository.countByRegistrationDate(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
358	    }
359	
360	    @Override
361	    @Transactional(readOnly = true)
362	    public long countNamesakes(String firstName, String lastName) throws DataAccessException {
363	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
364	            .filter(owner -> owner.getFirstName().equalsIgnoreCase(firstName))
365	            .count();
366	    }
367	
368	    /**
369	     * Assign the owner's deterministic {@code householdId}, derived from its last name and postcode,
370	     * so owners sharing a last name and postcode share the id automatically. Owners without a
371	     * postcode belong to no household and are left without an id.
372	     *
373	     * @return the assigned household id, or {@code null} when the owner has no postcode
374	     */
375	    @Override
376	    @Transactional
377	    public String assignHousehold(Owner owner) throws DataAccessException {
378	        if (owner.getPostcode() == null) {
379	            return null;
380	        }
381	        String householdId = householdIdGenerator.generate(owner.getLastName(), owner.getPostcode());
382	        owner.setHouseholdId(householdId);
383	        return householdId;
384	    }
385	
386	    /**
387	     * The number of members the owner's household will have once this (not yet persisted) owner is
388	     * created: the existing members sharing its household (last name and postcode), plus the owner
389	     * itself.
390	     */
391	    @Override
392	    @Transactional(readOnly = true)
393	    public long countHouseholdMembers(Owner owner) throws DataAccessException {
394	        return findHouseholdMembers(owner).size() + 1;
395	    }
396	
397	    /**
398	     * Resolve the membership level for a new owner, capping the level derived from its own membership
399	     * points so it never exceeds one above the current maximum level among its existing household
400	     * members. With no existing household member no cap applies and the derived level is returned.
401	     */
402	    @Override
403	    @Transactional(readOnly = true)
404	    public Integer resolveCappedMembershipLevel(Owner owner) throws DataAccessException {
405	        Integer derivedLevel = ownerMapper.deriveMembershipLevel(owner);
406	        return findHouseholdMembers(owner).stream()
407	            .map(ownerMapper::resolveMembershipLevel)
408	            .max(Integer::compareTo)
409	            .map(maxMemberLevel -> Math.min(derivedLevel, maxMemberLevel + 1))
410	            .orElse(derivedLevel);
411	    }
412	
413	    /**
414	     * Find the existing owners that share {@code owner}'s household, i.e. those with the same last
415	     * name (ignoring case) and the same postcode. An owner without a postcode belongs to no
416	     * household, so no members are returned for it. Soft-deleted owners are excluded, so they
417	     * neither block a create as a household duplicate nor count towards the household size.
418	     */
419	    private List<Owner> findHouseholdMembers(Owner owner) {
420	        if (owner.getPostcode() == null) {
421	            return List.of();
422	        }
423	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
424	            .filter(existing -> !existing.isDeleted())
425	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
426	            .toList();
427	    }
428	
429	    @Override
430	    @Transactional(readOnly = true)
431	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
432	        return ownerRepository.findByLastName(lastName);
433	    }
434	
435	    @Override
436	    @Transactional(readOnly = true)
437	    public Collection<Visit> findVisitsByPetId(int petId) {
438	        return visitRepository.findByPetId(petId);
439	    }
440	
441	    @Override
442	    @Transactional(readOnly = true)
443	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
444	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
445	    }
446	
447	    private <T> T findEntityById(Supplier<T> supplier) {
448	        try {
449	            return supplier.get();
450	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
451	            // Just ignore not found exceptions for Jdbc/Jpa realization
452	            return null;
453	        }
454	    }
455	
456	}
