19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles a {@link BusinessRuleViolationException} raised when a request is rejected by a
91	     * business rule, returning the rule's HTTP status with an RFC 7807 {@code problem+json} body.
92	     *
93	     * @param e The {@link BusinessRuleViolationException} to be handled
94	     * @param request {@link HttpServletRequest} object referring to the current request.
95	     * @return A {@link ResponseEntity} carrying the problem detail and the rule's HTTP status
96	     */
97	    @ExceptionHandler(BusinessRuleViolationException.class)
98	    @ResponseBody
99	    public ResponseEntity<ProblemDetail> handleBusinessRuleViolationException(BusinessRuleViolationException e, HttpServletRequest request) {
100	        logger.warn("Request rejected at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
101	        HttpStatus status = e.getStatus();
102	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
103	        detail.setTitle(e.getTitle());
104	        return ResponseEntity.status(status).body(detail);
105	    }
106	
107	    /**
108	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
109	     *
110	     * @param e The {@link Exception} to be handled
111	     * @param request {@link HttpServletRequest} object referring to the current request.
112	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
113	     */
114	    @ExceptionHandler(Exception.class)
115	    @ResponseBody
116	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
117	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
118	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
119	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
120	        return ResponseEntity.status(status).body(detail);
121	    }
122	
123	    /**
124	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
125	     * method returns a 404 Not Found status if an entity does not exist.
126	     *
127	     * @param e The {@link DataIntegrityViolationException} to be handled
128	     * @param request {@link HttpServletRequest} object referring to the current request.
129	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
130	     */
131	    @ExceptionHandler(DataIntegrityViolationException.class)
132	    @ResponseBody
133	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
134	        logger.warn("Data integrity violation at {} {}: {}",
135	            request.getMethod(),
136	            request.getRequestURI(),
137	            e.getMessage());
138	        logger.debug("Data integrity violation stacktrace", e);
139	        HttpStatus status = HttpStatus.NOT_FOUND;
140	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
141	        return ResponseEntity.status(status).body(detail);
142	    }
143	
144	    /**
145	     * Handles exception thrown by Bean Validation on controller methods parameters
146	     *
147	     * @param e The {@link MethodArgumentNotValidException} to be handled
148	     * @param request {@link HttpServletRequest} object referring to the current request.
149	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
150	     */
151	    @ExceptionHandler(MethodArgumentNotValidException.class)
152	    @ResponseBody
153	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
154	        HttpStatus status = HttpStatus.BAD_REQUEST;
155	        BindingErrorsResponse errors = new BindingErrorsResponse();
156	        BindingResult bindingResult = e.getBindingResult();
157	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
158	        if (bindingResult.hasErrors()) {
159	            errors.addAllErrors(bindingResult);
160	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
161	                .map(FieldError::getField)
162	                .distinct()
163	                .toList();
164	            detail.setProperty("errors", invalidFields);
165	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
166	                .map(fieldError -> {
167	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
168	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
169	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
170	                        fieldError.getField(),
171	                        defaultMessage,
172	                        rejectedValue);
173	                    return new ValidationMessageDto(message)
174	                        .putAdditionalProperty("field", fieldError.getField())
175	                        .putAdditionalProperty("rejectedValue", rejectedValue)
176	                        .putAdditionalProperty("defaultMessage", defaultMessage);
177	                })
178	                .toList();
179	            logger.debug("Validation error at {} {}: {}",
180	                request.getMethod(),
181	                request.getRequestURI(),
182	                bindingResult.getFieldErrors());
183	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
184	            return ResponseEntity.status(status).body(detail);
185	        }
186	        return ResponseEntity.status(status).body(detail);
187	    }
188	
189	}
