21	/**
22	 * Signals that a request was rejected by a business rule (as opposed to a framework-level
23	 * validation failure). Carries the HTTP status to return together with the short {@code title}
24	 * and human-readable {@code detail} that populate the RFC 7807 {@code application/problem+json}
25	 * response produced by {@link ExceptionControllerAdvice}.
26	 */
27	public class BusinessRuleViolationException extends RuntimeException {
28	
29	    private final HttpStatus status;
30	
31	    private final String title;
32	
33	    /**
34	     * @param status the HTTP status the rejection maps to (e.g. 400, 409, 429)
35	     * @param title  a short, human-readable summary of the problem type
36	     * @param detail a human-readable explanation specific to this occurrence
37	     */
38	    public BusinessRuleViolationException(HttpStatus status, String title, String detail) {
39	        super(detail);
40	        this.status = status;
41	        this.title = title;
42	    }
43	
44	    public HttpStatus getStatus() {
45	        return this.status;
46	    }
47	
48	    public String getTitle() {
49	        return this.title;
50	    }
51	}
