29	/**
30	 * Emits audit records for owner life-cycle events to the dedicated {@code AUDIT}
31	 * logger, keeping audit side-effects separate from the create business logic.
32	 */
33	@Component
34	public class OwnerAuditor {
35	
36	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
37	
38	    private final OwnerMapper ownerMapper;
39	
40	    private final ObjectMapper jsonMapper = JsonMapper.builder().build();
41	
42	    /** Sequence shared by every owner-created event, monotonically increasing across creates. */
43	    private final AtomicLong sequence = new AtomicLong();
44	
45	    public OwnerAuditor(OwnerMapper ownerMapper) {
46	        this.ownerMapper = ownerMapper;
47	    }
48	
49	    /**
50	     * Record the successful creation of an owner: a human-readable audit line plus an immutable
51	     * structured {@link OwnerCreatedEvent} serialized as JSON, both on the {@code AUDIT} logger.
52	     */
53	    public void auditCreated(Owner owner) {
54	        Integer membershipLevel = this.ownerMapper.resolveMembershipLevel(owner);
55	        String ownerSegment = this.ownerMapper.resolveOwnerSegment(owner);
56	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
57	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
58	        OwnerCreatedEvent event = new OwnerCreatedEvent(this.sequence.incrementAndGet(),
59	            owner.getId(), owner.getMemberId(), membershipLevel, ownerSegment);
60	        AUDIT.info(this.jsonMapper.writeValueAsString(event));
61	    }
62	}
