16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Optional;
19	import java.util.concurrent.ConcurrentHashMap;
20	import java.util.concurrent.ConcurrentMap;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Remembers which owner a given {@code Idempotency-Key} first created, so a repeated create
26	 * carrying an already-seen key can replay the original result instead of creating a duplicate.
27	 *
28	 * <p>The mapping is key &rarr; created owner id. A blank or absent key is never stored and never
29	 * matches, so requests without a key follow the ordinary create path.
30	 */
31	@Component
32	public class IdempotencyStore {
33	
34	    private final ConcurrentMap<String, Integer> ownerIdByKey = new ConcurrentHashMap<>();
35	
36	    /**
37	     * Look up the owner previously created under {@code key}.
38	     *
39	     * @param key the request's {@code Idempotency-Key} (may be {@code null} or blank)
40	     * @return the id of the originally created owner, or empty if the key is blank or unseen
41	     */
42	    public Optional<Integer> find(String key) {
43	        if (isBlank(key)) {
44	            return Optional.empty();
45	        }
46	        return Optional.ofNullable(this.ownerIdByKey.get(key));
47	    }
48	
49	    /**
50	     * Remember that {@code key} first created the owner with the given id. Blank keys are ignored
51	     * and an already-seen key keeps its original id, so the first create always wins.
52	     *
53	     * @param key     the request's {@code Idempotency-Key} (may be {@code null} or blank)
54	     * @param ownerId the id of the owner created for this key
55	     */
56	    public void record(String key, Integer ownerId) {
57	        if (isBlank(key)) {
58	            return;
59	        }
60	        this.ownerIdByKey.putIfAbsent(key, ownerId);
61	    }
62	
63	    private boolean isBlank(String key) {
64	        return key == null || key.isBlank();
65	    }
66	}
