16	package org.springframework.samples.petclinic.service;
17	
18	import java.time.LocalDate;
19	import java.util.Locale;
20	import java.util.function.Predicate;
21	
22	import org.springframework.samples.petclinic.rest.validation.LocalityResolver;
23	import org.springframework.samples.petclinic.util.FiscalYear;
24	import org.springframework.samples.petclinic.util.Luhn;
25	import org.springframework.samples.petclinic.util.OwnerIdentityVersion;
26	import org.springframework.samples.petclinic.util.Sha256;
27	import org.springframework.stereotype.Component;
28	
29	/**
30	 * Builds an owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} where REGION is the
31	 * version-2 {@linkplain OwnerIdentityVersion#regionCode(String) region code} (the canonical region
32	 * derived from the owner's postcode with the version tag mixed in), FY is the two-digit fiscal year
33	 * of the registration date, HASH8 is the first eight upper-case hex characters of the SHA-256 of the
34	 * owner's normalized telephone concatenated with the last name, and CHK is a single Luhn check digit
35	 * computed over the decimal digits of {@code <REGION><FY><HASH8>} (e.g. {@code "NSWV2261A2B3C4D9"}).
36	 */
37	@Component
38	public class MemberIdGenerator {
39	
40	    /** Number of leading hex characters of the SHA-256 digest kept as the identity hash. */
41	    private static final int HASH_LENGTH = 8;
42	
43	    /**
44	     * Build the member id for the given postcode, registration date, normalized telephone and last
45	     * name.
46	     *
47	     * @param postcode            the owner's postcode; its region forms the leading segment
48	     * @param registrationDate    the owner's registration date; its fiscal year forms the FY segment
49	     * @param normalizedTelephone the owner's telephone in canonical (E.164) form; hashed with the
50	     *                            last name to form the HASH8 segment
51	     * @param lastName            the owner's last name; hashed with the telephone
52	     * @return the formatted member id
53	     */
54	    public String generate(String postcode, LocalDate registrationDate, String normalizedTelephone,
55	            String lastName) {
56	        String region = OwnerIdentityVersion.regionCode(LocalityResolver.resolveFromPostcode(postcode));
57	        String fiscalYear = FiscalYear.twoDigit(registrationDate);
58	        String hash = Sha256.hex(normalizedTelephone + lastName)
59	            .substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
60	        String payload = region + fiscalYear + hash;
61	        return payload + Luhn.checkDigit(payload);
62	    }
63	
64	    /**
65	     * Return a member id that no existing owner already carries. If {@code memberId} is free it is
66	     * returned unchanged; otherwise {@code "-<n>"} is appended using the smallest {@code n} of two or
67	     * more that yields an unused id.
68	     *
69	     * @param memberId the freshly generated id that may collide with an existing owner's id
70	     * @param isTaken  predicate reporting whether a candidate id is already in use
71	     * @return an id guaranteed not to collide with an existing owner's id
72	     */
73	    public String deduplicate(String memberId, Predicate<String> isTaken) {
74	        if (!isTaken.test(memberId)) {
75	            return memberId;
76	        }
77	        for (int n = 2; ; n++) {
78	            String candidate = memberId + "-" + n;
79	            if (!isTaken.test(candidate)) {
80	                return candidate;
81	            }
82	        }
83	    }
84	}
